//! JavaScript parity gate: extract the `sample` JS corpus with `habitat-graph` and compare
//! against the committed golden, per relation.
//!
//! The golden (`tests/fixtures/goldens/js/graph.json`) was generated by the
//! `gen_golden_js` example using the same JS extractor and pinned as the authoritative
//! reference for regression detection.  Because we are the first and only JS extractor
//! (no external Python oracle exists for JS), the golden encodes our own committed output —
//! any drop is OUR regression; any rise means the extractor improved and should be ratcheted.
//!
//! Coverage design:
//!   - 20 nodes: file, 4 standalone fns/arrows, 3 classes + their 12 methods.
//!   - 20 structural edges: 7 `contains` + 12 `method` + 1 `inherits` (local Animal→Dog).
//!   - 0 `imports_from`/`calls`/`uses` in the golden — external import targets (events,
//!     fs/promises, path) and external bases (EventEmitter) are never nodes in a
//!     single-file corpus, so `assemble` drops those dangling edges (documented policy).
//!
//! Per the parity strategy (`ai_docs/06_PARITY_INTEL`): structural relations
//! (`contains` / `method` / `inherits` / `imports_from`) are expected to be well-covered;
//! `calls` / `uses` are deliberately NOT emitted, reported as documented divergence.

use std::path::PathBuf;

use habitat_graph_fixtures::{classify, from_core, from_golden};

/// Pinned-oracle baseline (LS-3): verified-good JS coverage. Any drop is OUR regression.
/// Ratchet UP when extraction legitimately improves.
///
/// 20/20 nodes (100%): all locally-defined symbols fully covered.
const JS_NODE_BASELINE: usize = 20;

/// 20/20 structural edges (100%): all contains + method + inherits edges covered.
/// External import/inherits edges are dangling and are not structural regressions
/// when only a single-file corpus is used.
const JS_STRUCT_BASELINE: usize = 20;

fn js_dir() -> PathBuf {
    PathBuf::from(format!(
        "{}/../../tests/fixtures/goldens/js",
        env!("CARGO_MANIFEST_DIR")
    ))
}

// ── 1. Primary parity gate ────────────────────────────────────────────────────────────────────

#[test]
fn js_structural_parity() {
    let dir = js_dir();

    // Our extraction: detect → extract → assemble → normalize.
    let files =
        habitat_graph_source::detect(&dir.join("raw"), &["js"]).expect("detect .js files");
    assert!(!files.is_empty(), "must find at least one JS file under goldens/js/raw");

    let extractions = habitat_graph_extract::extract_files(&files).expect("extract");
    let graph = habitat_graph_build::assemble(extractions);
    let ours = from_core(&graph);

    // Golden (our committed reference — see module-level docs).
    let golden_json =
        std::fs::read_to_string(dir.join("graph.json")).expect("read js golden graph.json");
    let golden = from_golden(&golden_json).expect("parse js golden");

    let report = classify(&ours, &golden);

    let node_total = golden.nodes.len().max(1);
    let node_pct = (report.nodes_matched * 100 + node_total / 2) / node_total;
    eprintln!("\n=== JS sample parity ===");
    eprintln!(
        "NODES: {}/{} golden ids covered ({node_pct}%), {} extra",
        report.nodes_matched,
        golden.nodes.len(),
        report.nodes_extra.len()
    );

    eprintln!("EDGES by relation (matched / golden / ours):");
    let mut structural_matched = 0_usize;
    let mut structural_total = 0_usize;
    for rel in [
        "contains",
        "method",
        "inherits",
        "imports_from",
        "calls",
        "uses",
    ] {
        let g = golden.edges_with_relation(rel);
        let o = ours.edges_with_relation(rel);
        let matched = g.intersection(&o).count();
        eprintln!("  {rel:>12}: {matched} / {} / {}", g.len(), o.len());
        if matches!(rel, "contains" | "method" | "inherits" | "imports_from") {
            structural_matched += matched;
            structural_total += g.len();
        }
    }
    let struct_total = structural_total.max(1);
    let struct_pct = (structural_matched * 100 + struct_total / 2) / struct_total;
    eprintln!("STRUCTURAL coverage: {structural_matched}/{structural_total} ({struct_pct}%)\n");

    if !report.nodes_missing.is_empty() {
        eprintln!("MISSING NODES: {:?}", report.nodes_missing);
    }
    if !report.edges_missing.is_empty() {
        eprintln!("MISSING EDGES: {:?}", report.edges_missing);
    }

    // Regression gate (LS-3): assert against the PINNED-ORACLE BASELINE, not a loose floor.
    // The golden is pinned, so any drop in coverage is OUR regression. Ratchet UP on improvement.
    assert!(
        report.nodes_matched >= JS_NODE_BASELINE,
        "node coverage REGRESSED: {}/{} ({node_pct}%) < pinned baseline {JS_NODE_BASELINE} — \
         reconcile or ratchet",
        report.nodes_matched,
        golden.nodes.len()
    );
    assert!(
        structural_matched >= JS_STRUCT_BASELINE,
        "structural coverage REGRESSED: {structural_matched}/{structural_total} ({struct_pct}%) \
         < pinned baseline {JS_STRUCT_BASELINE} (LS-3)"
    );
}

// ── 2. Golden sanity: known node ids ─────────────────────────────────────────────────────────

#[test]
fn js_golden_has_file_node() {
    let dir = js_dir();
    let json = std::fs::read_to_string(dir.join("graph.json")).expect("read golden");
    let g = from_golden(&json).expect("parse golden");
    assert!(
        g.nodes.contains("sample"),
        "golden must contain file node 'sample'"
    );
}

