#[test]
fn our_extraction_drops_external_inherits_edge() {
    // EventEmitter is not a node in the graph → the inherits edge is a dangling edge and
    // must be dropped by assemble (documented policy).
    let dir = js_dir();
    let files =
        habitat_graph_source::detect(&dir.join("raw"), &["js"]).expect("detect");
    let extractions = habitat_graph_extract::extract_files(&files).expect("extract");
    let graph = habitat_graph_build::assemble(extractions);
    let ours = from_core(&graph);
    assert!(
        !ours.nodes.contains("eventemitter"),
        "external base 'eventemitter' must NOT appear as a node"
    );
    let external_inherits = ours
        .edges
        .iter()
        .any(|(src, _, rel)| src == "eventemitter" && rel == "inherits");
    assert!(
        !external_inherits,
        "external inherits edge (eventemitter → sample_eventbus) must be dropped by assemble"
    );
}

#[test]
fn our_extraction_emits_no_calls_or_uses_edges() {
    let dir = js_dir();
    let files =
        habitat_graph_source::detect(&dir.join("raw"), &["js"]).expect("detect");
    let extractions = habitat_graph_extract::extract_files(&files).expect("extract");
    let graph = habitat_graph_build::assemble(extractions);
    let ours = from_core(&graph);
    for forbidden in ["calls", "uses"] {
        let count = ours.edges_with_relation(forbidden).len();
        assert_eq!(count, 0, "'{forbidden}' edges must never be emitted");
    }
}

#[test]
fn js_golden_parses_without_error() {
    let dir = js_dir();
    let json = std::fs::read_to_string(dir.join("graph.json")).expect("read golden");
    assert!(
        from_golden(&json).is_ok(),
        "js golden must parse cleanly"
    );
}

#[test]
fn js_golden_node_set_is_deterministic() {
    let dir = js_dir();
    let json = std::fs::read_to_string(dir.join("graph.json")).expect("read golden");
    let g1 = from_golden(&json).expect("first parse");
    let g2 = from_golden(&json).expect("second parse");
    assert_eq!(g1.nodes, g2.nodes, "node set must be deterministic");
    assert_eq!(g1.edges, g2.edges, "edge set must be deterministic");
}
